int trap(vector<int>& h) {
    int l = 0, r = h.size() - 1;
    int lmax = 0, rmax = 0, ans = 0;
    while (l < r) {
        lmax = max(lmax, h[l]);
        rmax = max(rmax, h[r]);
        if (lmax < rmax) {
            ans += lmax - h[l];  // 左边是短板
            l++;
        } else {
            ans += rmax - h[r];  // 右边是短板
            r--;
        }
    }
    return ans;
}
// 核心：双指针+两端最大高度 | 移动短板一侧 | 每列贡献=min(lmax,rmax)-h[i]
